class MissingAttenuatorSetup(Exception):
    """ Raised when attenuator setup was not performed before. """
    pass


class IncorrectAttenuationMode(Exception):
    """ Raised when incorrect attenuation mode was provided. """
    pass


class IncorrectParameterValue(Exception):
    """ Raised when incorrect parameter value was provided. """
    pass


class RebootNotExecuted(Exception):
    """
    Raised when reboot on HTTP webpage of attenuator could not be processed.
    """
    pass


class ProgrammableAttenuatorError(Exception):
    """
    Raised when an error occurs on the programmable attenuator.
    """
    pass


class AttenuatorRebootFailed(Exception):
    """
    Raised when programmable attenuator reboot procedure fails on any step.
    """
